function listPosts({url,$}) {const posts=[]; $('a[href^="/blogs/post/"]').each((_,e)=>{const a=$(e); posts.push({url:a.attr('href'),title:a.text().trim(),publishedAt:a.closest('article').find('time').attr('datetime')||null});});return {posts,next:null};}
function parsePost({url,$}) {
 const title=$(".container > h1").first().text().trim(); const body=$(".blur-container.container").first().clone();
 body.children('h1,.json-container').remove(); body.find('script,style,noscript').remove();
 let ld={}; $('script[type="application/ld+json"]').each((_,e)=>{try{const v=JSON.parse($(e).text());const walk=x=>{if(Array.isArray(x))x.forEach(walk);else if(x&&typeof x==='object'){if(/Article|Posting/i.test(String(x['@type']||'')))ld=x;if(x['@graph'])walk(x['@graph']);}};walk(v);}catch{}});
 let info={}; try{info=JSON.parse($('.json-container code').first().text());}catch{} const author=info['作者']||$('meta[name="author"]').attr('content')||$('a[rel="author"],.article-author,.gh-author-name,.author-name').first().text().trim()||(typeof ld.author==='string'?ld.author:Array.isArray(ld.author)?ld.author.map(a=>a.name).join(', '):ld.author?.name)||null;
 const publishedAt=info['撰寫日期']?.replaceAll('/', '-')||$('meta[property="article:published_time"],meta[itemprop="datePublished"]').first().attr('content')||$('time[datetime]').first().attr('datetime')||ld.datePublished||null;
 const tags=Array.isArray(ld.keywords)?ld.keywords:$('a[rel="tag"],.post-tags a,.article-tags a,.tags a,a[href^="/tags/"]').map((_,e)=>$(e).text().trim().replace(/^#/, '')).get();
 return {title,bodyHtml:body.html()||'',author,publishedAt,tags};
}
